        internal static bool TryGet(string language, string key, out string value)
        {
            if (string.Equals(language, "uk", StringComparison.OrdinalIgnoreCase)) language = "UA";
            if (language != null && Data.TryGetValue(language, out var dict) && dict.TryGetValue(key, out value)) return true;
            value = null;
            return false;
        }
    }
